215	impl Workspace for WorkspaceServer {
216	    fn file_features(
217	        &self,
218	        params: SupportsFeatureParams,
219	    ) -> Result<FileFeaturesResult, WorkspaceError> {
220	        let file_features_result = self.file_features.entry(params.path.clone());
221	        match file_features_result {
222	            Entry::Occupied(entry) => {
223	                let result = entry.get();
224	                Ok(result.clone())
225	            }
226	            Entry::Vacant(entry) => {
227	                let capabilities = self.get_file_capabilities(&params.path);
228	                let language = Language::from_path(&params.path);
229	                let path = params.path.as_path();
230	                let settings = self.settings.read().unwrap();
231	                let mut file_features = FileFeaturesResult::new();
232	
233	                file_features = file_features
234	                    .with_capabilities(&capabilities)
235	                    .with_settings_and_language(&settings, &language, path);
236	
237	                if settings.files.ignore_unknown
238	                    && language == Language::Unknown
239	                    && self.get_language(&params.path) == Language::Unknown
240	                {
241	                    file_features.ignore_not_supported();
242	                } else {
243	                    for feature in params.feature {
244	                        let is_ignored = self.is_path_ignored(IsPathIgnoredParams {
245	                            rome_path: params.path.clone(),
246	                            feature: feature.clone(),
247	                        })?;
248	                        if is_ignored {
249	                            file_features.ignored(feature);
250	                        }
251	                    }
252	                }
253	
254	                // If the file is not ignored by at least one feature,
255	                // then check that the file is not protected.
256	                // Protected files must be ignored.
257	                if !file_features.is_not_processed() && FileFeaturesResult::is_protected_file(path)
258	                {
259	                    file_features.set_protected_for_all_features();
260	                }
261	
262	                Ok(entry.insert(file_features).clone())
263	            }
264	        }
265	    }
266	
267	    fn is_path_ignored(&self, params: IsPathIgnoredParams) -> Result<bool, WorkspaceError> {
268	        let settings = self.settings();
269	        let path = params.rome_path.as_path();
270	        if path.file_name().and_then(|s| s.to_str()) == Some(BIOME_JSON) {
271	            return Ok(false);
272	        }
273	
274	        // Overrides have top priority
275	        let excluded_by_override = settings.as_ref().override_settings.is_path_excluded(path);
276	        if excluded_by_override.unwrap_or_default() {
277	            return Ok(true);
278	        }
279	        let included_by_override = settings.as_ref().override_settings.is_path_included(path);
280	        if included_by_override.unwrap_or_default() {
281	            return Ok(false);
282	        }
283	
284	        let (ignored_files, included_files) = match params.feature {
285	            FeatureName::Format => {
286	                let formatter = &settings.as_ref().formatter;
287	                (&formatter.ignored_files, &formatter.included_files)
288	            }
289	            FeatureName::Lint => {
290	                let linter = &settings.as_ref().linter;
291	                (&linter.ignored_files, &linter.included_files)
292	            }
293	            FeatureName::OrganizeImports => {
294	                let organize_imports = &settings.as_ref().organize_imports;
295	                (
296	                    &organize_imports.ignored_files,
297	                    &organize_imports.included_files,
298	                )
299	            }
300	        };
301	
302	        // Tool include/ignore have priority over (global) files include/ignore
303	        if ignored_files.matches_path(path) {
304	            return Ok(true);
305	        }
306	        if !included_files.is_empty() && included_files.matches_path(path) {
307	            return Ok(false);
308	        }
309	
310	        Ok(self.is_ignored_by_top_level_config(path))
311	    }
