87	    #[tracing::instrument(level = "trace", skip(self))]
88	    pub fn merge_with_configuration(
89	        &mut self,
90	        configuration: Configuration,
91	        working_directory: Option<PathBuf>,
92	        vcs_path: Option<PathBuf>,
93	        gitignore_matches: &[String],
94	    ) -> Result<(), WorkspaceError> {
95	        // formatter part
96	        if let Some(formatter) = configuration.formatter {
97	            self.formatter = to_format_settings(
98	                working_directory.clone(),
99	                formatter,
100	                vcs_path.clone(),
101	                gitignore_matches,
102	            )?;
103	        }
104	
105	        // linter part
106	        if let Some(linter) = configuration.linter {
107	            self.linter = to_linter_settings(
108	                working_directory.clone(),
109	                linter,
110	                vcs_path.clone(),
111	                gitignore_matches,
112	            )?;
113	        }
114	
115	        // Filesystem settings
116	        if let Some(files) = to_file_settings(
117	            working_directory.clone(),
118	            configuration.files,
119	            vcs_path.clone(),
120	            gitignore_matches,
121	        )? {
122	            self.files = files;
123	        }
124	
125	        if let Some(organize_imports) = configuration.organize_imports {
126	            self.organize_imports = to_organize_imports_settings(
127	                working_directory.clone(),
128	                organize_imports,
129	                vcs_path.clone(),
130	                gitignore_matches,
131	            )?;
132	        }
133	
134	        // javascript settings
135	        if let Some(javascript) = configuration.javascript {
136	            self.languages.javascript = javascript.into();
137	        }
138	        // json settings
139	        if let Some(json) = configuration.json {
140	            self.languages.json = json.into();
141	        }
142	        // css settings
143	        if let Some(css) = configuration.css {
144	            self.languages.css = css.into();
145	        }
146	
147	        // NOTE: keep this last. Computing the overrides require reading the settings computed by the parent settings.
148	        if let Some(overrides) = configuration.overrides {
149	            self.override_settings = to_override_settings(
