161	    /// It retrieves the severity based on the `code` of the rule and the current configuration.
162	    ///
163	    /// The code of the has the following pattern: `{group}/{rule_name}`.
164	    ///
165	    /// It returns [None] if the `code` doesn't match any rule.
166	    pub fn get_severity_from_rule_code(
167	        &self,
168	        code: &Category,
169	    ) -> Option<biome_diagnostics::Severity> {
170	        let rules = self.linter.rules.as_ref();
171	        if let Some(rules) = rules {
172	            rules.get_severity_from_code(code)
173	        } else {
174	            None
175	        }
