117	    /// It matches the given path against the stored patterns
118	    ///
119	    /// It returns [true] if there's a lest a match
120	    pub fn matches_path(&self, source: &Path) -> bool {
121	        if self.is_empty() {
122	            return false;
123	        }
124	        let mut already_checked = self.already_checked.write().unwrap();
125	        let source_as_string = source.to_str();
126	        if let Some(source_as_string) = source_as_string {
127	            if let Some(matches) = already_checked.get(source_as_string) {
128	                return *matches;
129	            }
130	        }
131	        let matches = self.run_match(source);
132	
133	        if let Some(source_as_string) = source_as_string {
134	            already_checked.insert(source_as_string.to_string(), matches);
135	        }
136	
137	        matches
138	    }
