140	    fn run_match(&self, source: &Path) -> bool {
141	        for pattern in &self.patterns {
142	            let matches = if pattern.matches_path_with(source, self.options) {
143	                true
144	            } else {
145	                // Here we cover cases where the user specifies single files inside the patterns.
146	                // The pattern library doesn't support single files, we here we just do a check
147	                // on contains
148	                //
149	                // Given the pattern `out`:
150	                // - `out/index.html` -> matches
151	                // - `out/` -> matches
152	                // - `layout.tsx` -> does not match
153	                // - `routes/foo.ts` -> does not match
154	                source
155	                    .ancestors()
156	                    .any(|ancestor| ancestor.ends_with(pattern.as_str()))
157	            };
158	
159	            if matches {
160	                return true;
161	            }
162	        }
163	
164	        if let Some(source_as_string) = source.to_str() {
165	            if self
166	                .git_ignore
167	                .as_ref()
168	                .map(|ignore| {
169	                    ignore
170	                        .matched_path_or_any_parents(source_as_string, source.is_dir())
