159	    working_directory: Option<PathBuf>,
160	    overrides: Overrides,
161	    vcs_base_path: Option<PathBuf>,
162	    gitignore_matches: &[String],
163	    current_settings: &WorkspaceSettings,
164	) -> Result<OverrideSettings, WorkspaceError> {
165	    let mut override_settings = OverrideSettings::default();
166	    for mut pattern in overrides.0 {
