168	        let formatter = to_format_settings(formatter, &current_settings.formatter);
169	
170	        let linter = pattern.linter.take().unwrap_or_default();
171	        let linter = to_override_linter_settings(linter, &current_settings.linter);
172	
173	        let organize_imports = pattern.organize_imports.take().unwrap_or_default();
174	        let organize_imports =
175	            to_organize_imports_settings(organize_imports, &current_settings.organize_imports);
176	
177	        let mut languages = LanguageListSettings::default();
178	        let javascript = pattern.javascript.take().unwrap_or_default();
179	        let json = pattern.json.take().unwrap_or_default();
180	        let css = pattern.css.take().unwrap_or_default();
181	        languages.javascript =
182	            to_javascript_language_settings(javascript, &current_settings.languages.javascript);
183	
184	        languages.json = to_json_language_settings(json, &current_settings.languages.json);
185	        languages.css = to_css_language_settings(css, &current_settings.languages.css);
186	
187	        let pattern_setting = OverrideSettingPattern {
188	            include: to_matcher(
189	                working_directory.clone(),
190	                pattern.include.as_ref(),
191	                vcs_base_path.clone(),
192	                gitignore_matches,
193	            )?,
194	            exclude: to_matcher(
