861	/// Creates a [Matcher] from a [StringSet]
862	///
863	/// ## Errors
864	///
865	/// It can raise an error if the patterns aren't valid
866	pub fn to_matcher(
867	    working_directory: Option<PathBuf>,
868	    string_set: Option<&StringSet>,
869	    vcs_path: Option<PathBuf>,
870	    git_ignore_matches: &[String],
871	) -> Result<Matcher, WorkspaceError> {
872	    let mut matcher = Matcher::empty();
873	    if let Some(working_directory) = working_directory {
874	        matcher.set_root(working_directory)
875	    }
876	    if let Some(string_set) = string_set {
877	        for pattern in string_set.iter() {
878	            matcher.add_pattern(pattern).map_err(|err| {
879	                WorkspaceError::Configuration(ConfigurationDiagnostic::new_invalid_ignore_pattern(
880	                    pattern.to_string(),
881	                    err.msg.to_string(),
882	                ))
883	            })?;
884	        }
885	    }
886	    if let Some(vcs_path) = vcs_path {
887	        matcher.add_gitignore_matches(vcs_path, git_ignore_matches)?;
888	    }
889	    Ok(matcher)
